	"xpdevs"	INTEGER NOT NULL DEFAULT 0,
	"xpdevt"	INTEGER NOT NULL DEFAULT 0,
	"xpdevi"	INTEGER NOT NULL DEFAULT 0,
	"onmarket"	INTEGER NOT NULL DEFAULT 0,
	"face"	INTEGER NOT NULL DEFAULT 1,
	"country"	INTEGER NOT NULL DEFAULT 1,
	"fitness"	INTEGER NOT NULL DEFAULT 1,
	"morale"	INTEGER NOT NULL DEFAULT 1,
	"young"	INTEGER NOT NULL DEFAULT 0,
	"matchcost"	INTEGER NOT NULL DEFAULT 0,
