	"lvcrossing"	INTEGER NOT NULL DEFAULT 1,
	"lvheading"	INTEGER NOT NULL DEFAULT 1,
	"lvworkrate"	INTEGER NOT NULL DEFAULT 1,
	"lvdetermination"	INTEGER NOT NULL DEFAULT 1,
	"lvbravery"	INTEGER NOT NULL DEFAULT 1,
	"lvintuition"	INTEGER NOT NULL DEFAULT 1,
	"lvstrenght"	INTEGER NOT NULL DEFAULT 1,
	"lvagility"	INTEGER NOT NULL DEFAULT 1,
	"lvtechnique"	INTEGER NOT NULL DEFAULT 1,
