	"lvpressingdone"	INTEGER NOT NULL DEFAULT 1,
	"lvbonustackleturn"	INTEGER NOT NULL DEFAULT 1,
	"lvbonuslopballcontrolturn"	INTEGER NOT NULL DEFAULT 1,
	"lvbonusprotectionturn"	INTEGER NOT NULL DEFAULT 1,
	"lvnderressureurn"	INTEGER NOT NULL DEFAULT 1,
