	"lvteamturn"	INTEGER NOT NULL DEFAULT 0,
	"lvactionpoints"	INTEGER NOT NULL DEFAULT 0,
	"lvflagendgame"	INTEGER NOT NULL DEFAULT 0,
	"lvfinished"	INTEGER NOT NULL DEFAULT 0,
	"lvlowpassbuff"	INTEGER NOT NULL DEFAULT 0,
	"lvlowpassfree"	INTEGER NOT NULL DEFAULT 0,
	"lvincmove"	INTEGER NOT NULL DEFAULT 0,
