	"lvw_Fka1"	INTEGER NOT NULL DEFAULT 0,
	"lvw_FreeKick1"	INTEGER DEFAULT NULL,
	"lvw_FreeKickSetup2"	INTEGER NOT NULL DEFAULT 0,
	"lvw_Fka2"	INTEGER DEFAULT NULL,
	"lvw_Fkd2"	INTEGER DEFAULT NULL,
