	"lvw_FreeKickSetup3"	INTEGER NOT NULL DEFAULT 0,
	"lvw_Fka3"	INTEGER DEFAULT NULL,
	"lvw_Fkd3"	INTEGER DEFAULT NULL,
	"lvw_FreeKick3"	INTEGER NOT NULL DEFAULT 0,
