	"lvw_Fka4"	INTEGER DEFAULT NULL,
	"lvw_FreeKick4"	INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("guid" AUTOINCREMENT)
);
DROP TABLE IF EXISTS "save";
CREATE TABLE "save" (
	"guidteam"	INTEGER NOT NULL DEFAULT 0,
	"teamname"	TEXT DEFAULT NULL,
	"country"	INTEGER NOT NULL DEFAULT 0,
	"season"	INTEGER DEFAULT 0,
	"round"	INTEGER DEFAULT 0,
	"division"	INTEGER DEFAULT 5,
	"countryname"	TEXT DEFAULT NULL,
	"uniformh"	TEXT DEFAULT '1,1,1,1',
	"uniforma"	TEXT DEFAULT '1,1,1,1'
);
DROP TABLE IF EXISTS "teams";
CREATE TABLE "teams" (
	"guid"	INTEGER,
	"worldteam"	INTEGER NOT NULL DEFAULT 0,
	"country"	INTEGER NOT NULL DEFAULT 0,
	"teamname"	TEXT NOT NULL,
	"nextha"	INTEGER NOT NULL DEFAULT 0,
	"money"	INTEGER NOT NULL DEFAULT 500,
	"uniformh"	TEXT DEFAULT '0,0,0,0',
	"uniforma"	TEXT DEFAULT '1,1,1,1',
	"bot"	INTEGER NOT NULL DEFAULT 0,
	"mi"	INTEGER NOT NULL DEFAULT 0,
	"points"	INTEGER NOT NULL DEFAULT 0,
	"matchesplayed"	INTEGER NOT NULL DEFAULT 0,
	"season"	INTEGER NOT NULL DEFAULT 1,
	"division"	INTEGER NOT NULL DEFAULT 0,
	"youngqueue"	INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("guid" AUTOINCREMENT)
);
DROP TABLE IF EXISTS "transfers";
CREATE TABLE "transfers" (
	"guid"	INTEGER,
	"action"	TEXT DEFAULT NULL,
	"seller"	INTEGER NOT NULL DEFAULT 0,
	"buyer"	INTEGER NOT NULL DEFAULT 0,
	"playerguid"	INTEGER NOT NULL DEFAULT 0,
	"price"	INTEGER NOT NULL DEFAULT 0,
	"actiondate"	TEXT DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("guid" AUTOINCREMENT)
);
COMMIT;
